using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpServer.Tools;

[McpServerToolType]
public class ApiFetchTool
{
    [McpServerTool, Description("Fetches data from an external API endpoint via HTTP GET and returns the response body.")]
    public static async Task<string> FetchApi(
        HttpClient httpClient,
        [Description("The full URL to fetch (e.g. https://api.example.com/data)")] string url,
        CancellationToken cancellationToken)
    {
        if (!Uri.TryCreate(url, UriKind.Absolute, out var uri) ||
            (uri.Scheme != "https" && uri.Scheme != "http"))
        {
            return JsonSerializer.Serialize(new { error = "Invalid URL. Provide an absolute HTTP(S) URL." });
        }

        try
        {
            var response = await httpClient.GetAsync(uri, cancellationToken);
            var body = await response.Content.ReadAsStringAsync(cancellationToken);

            return JsonSerializer.Serialize(new
            {
                status = (int)response.StatusCode,
                body
            });
        }
        catch (HttpRequestException ex)
        {
            return JsonSerializer.Serialize(new { error = ex.Message });
        }
        catch (TaskCanceledException)
        {
            return JsonSerializer.Serialize(new { error = "Request timed out." });
        }
    }
}

using Microsoft.Extensions.AI;
using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpServer.Prompts;

[McpServerPromptType]
public class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the given text in a specified style.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Summary style: brief, detailed, or bullet-points (default: brief)")] string style = "brief")
    {
        var instruction = style.ToLowerInvariant() switch
        {
            "detailed" => "Provide a detailed summary that captures all key points and nuances.",
            "bullet-points" => "Summarize the text as a concise list of bullet points.",
            _ => "Provide a brief, one-paragraph summary of the key points.",
        };

        return
        [
            new(ChatRole.User,
                $"""
                 {instruction}

                 Text to summarize:
                 {text}
                 """),
        ];
    }
}

